{%- if renewals.size > 0 -%}
<ul class="renewals">
{%- for r in renewals -%}
{%- if r.status == "paid" -%}
<li>Term {{ forloop.index }}: {{ r.plan | escape }}</li>
{%- else -%}
<li class="lapsed">Lapsed: {{ r.plan | escape }}</li>
{%- endif -%}
{%- endfor -%}
</ul>
{%- endif -%}

{%- if renewals.size > 0 -%}
{%- assign term = 0 -%}
<ul class="renewals">
